begin;
update public.questions set options = '[{"id": "a", "body": "The Court wished to give Parliament time to pass a new amendment that would restore its power to amend Fundamental Rights", "body_hi": "न्यायालय संसद को एक नया संशोधन पारित करने का समय देना चाहता था, जिससे मौलिक अधिकारों में संशोधन की उसकी शक्ति लौट आए", "isCorrect": false}, {"id": "b", "body": "The doctrine let the Court strike down the First, Fourth and Seventeenth Amendments while keeping the laws made under them", "body_hi": "इस सिद्धांत से न्यायालय पहला, चौथा और सत्रहवाँ संशोधन रद्द कर सका, जबकि उनके तहत बने क़ानून बने रहे", "isCorrect": false}, {"id": "c", "body": "The Court was bound by Article 141 to follow the earlier Shankari Prasad and Sajjan Singh rulings for all past cases, whatever its own view", "body_hi": "अनुच्छेद 141 के कारण न्यायालय अपने मत के बावजूद सभी पुराने मामलों में शंकरी प्रसाद और सज्जन सिंह के निर्णयों से बँधा था", "isCorrect": false}, {"id": "d", "body": "Applying it to the past would have voided earlier amendments and the land reforms resting on them, so it bound only future amendments", "body_hi": "इसे अतीत पर लागू करने से पहले के संशोधन और उन पर टिके भूमि सुधार शून्य हो जाते, इसलिए यह केवल भविष्य के संशोधनों पर लागू हुआ", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'polity-prospective-overruling-golaknath' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "The Council of Ministers is collectively responsible to the lower House", "body_hi": "मंत्रिपरिषद सामूहिक रूप से निचले सदन के प्रति उत्तरदायी है", "isCorrect": false}, {"id": "b", "body": "The head of State is nominal, and real power lies with the Council of Ministers", "body_hi": "राष्ट्राध्यक्ष नाममात्र का है, और वास्तविक शक्ति मंत्रिपरिषद के पास है", "isCorrect": false}, {"id": "c", "body": "The Prime Minister is normally the leader of the majority in the lower House", "body_hi": "प्रधानमंत्री सामान्यतः निचले सदन में बहुमत के नेता होते हैं", "isCorrect": false}, {"id": "d", "body": "Courts can strike down laws made by Parliament for violating the Constitution", "body_hi": "न्यायालय संविधान का उल्लंघन करने वाले संसद के क़ानूनों को रद्द कर सकते हैं", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'polity-not-a-feature-presidential' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "A Bill raising the fees charged for issuing passports", "body_hi": "पासपोर्ट जारी करने की फ़ीस बढ़ाने वाला विधेयक", "isCorrect": false}, {"id": "b", "body": "A Bill imposing fines for the misuse of government land", "body_hi": "सरकारी भूमि के दुरुपयोग पर जुर्माना लगाने वाला विधेयक", "isCorrect": false}, {"id": "c", "body": "A Bill allowing municipalities to levy a tax on hoardings", "body_hi": "नगरपालिकाओं को होर्डिंग पर कर लगाने की अनुमति देने वाला विधेयक", "isCorrect": false}, {"id": "d", "body": "A Bill imposing a new cess on crude oil", "body_hi": "कच्चे तेल पर नया उपकर लगाने वाला विधेयक", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'parl-money-bill-fines-not' returning concept_group_id;
