update public.questions set options = '[{"id": "a", "body": "A party that won 2 per cent of the Lok Sabha seats, all of them from two States", "body_hi": "ऐसा दल जिसने लोकसभा की 2 प्रतिशत सीटें जीतीं, पर सभी केवल दो राज्यों से", "isCorrect": false}, {"id": "b", "body": "A party that polled 6 per cent of the valid votes in three States and won four Lok Sabha seats", "body_hi": "ऐसा दल जिसने तीन राज्यों में 6 प्रतिशत वैध मत पाए और लोकसभा की चार सीटें जीतीं", "isCorrect": false}, {"id": "c", "body": "A party that won eleven Lok Sabha seats, all of them from a single State", "body_hi": "ऐसा दल जिसने लोकसभा की ग्यारह सीटें जीतीं, पर सभी एक ही राज्य से", "isCorrect": false}, {"id": "d", "body": "A party recognised as a State party in four States", "body_hi": "चार राज्यों में राज्य दल के रूप में मान्यता प्राप्त दल", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'elections-national-party-four-states' returning concept_group_id;
