update public.questions set options = '[{"id": "a", "body": "a Congress decision to replace the provincial kisan sabhas with a single wing under its Working Committee", "body_hi": "प्रांतीय किसान सभाओं की जगह अपनी कार्यसमिति के अधीन एक ही शाखा बनाने के कांग्रेस के निर्णय का", "isCorrect": false}, {"id": "b", "body": "the Muslim League''s effort to win over the tenants of eastern Bengal before the 1937 elections", "body_hi": "1937 के चुनावों से पहले पूर्वी बंगाल के काश्तकारों को अपनी ओर करने के मुस्लिम लीग के प्रयास का", "isCorrect": false}, {"id": "c", "body": "the government''s attempt to build a loyal body of peasants to counter the Congress", "body_hi": "कांग्रेस का सामना करने के लिए किसानों का एक वफ़ादार निकाय बनाने के सरकार के प्रयास का", "isCorrect": false}, {"id": "d", "body": "the rise of the Left in the national movement, seeking to organise peasants on their own demands", "body_hi": "राष्ट्रीय आंदोलन में वामपंथ के उभार का, जो किसानों को उनकी अपनी माँगों पर संगठित करना चाहता था", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'modern-all-india-kisan-sabha-1936' returning concept_group_id;
