update public.questions set options = '[{"id": "a", "body": "the Nandas were a foreign dynasty that had entered north-western India with the Persian armies", "body_hi": "नंद एक विदेशी वंश था जो फ़ारसी सेनाओं के साथ उत्तर-पश्चिमी भारत में आया था", "isCorrect": false}, {"id": "b", "body": "Mahapadma Nanda had converted to Buddhism and persecuted the Brahmanas and the Kshatriyas", "body_hi": "महापद्म नंद ने बौद्ध धर्म अपनाकर ब्राह्मणों और क्षत्रियों पर अत्याचार किया था", "isCorrect": false}, {"id": "c", "body": "the Puranas were composed by the Nandas'' own court poets to praise their rise to power", "body_hi": "पुराण नंदों के अपने दरबारी कवियों ने उनके उत्थान की प्रशंसा में रचे थे", "isCorrect": false}, {"id": "d", "body": "the Nandas broke the norm that kings should be Kshatriyas, and Brahmanical authors resented it", "body_hi": "नंदों ने इस मान्यता को तोड़ा कि राजा क्षत्रिय होने चाहिए, और ब्राह्मणवादी लेखकों को यह अखरा", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'ancient-mahapadma-nanda' returning concept_group_id;
