update public.questions set options = '[{"id": "a", "body": "She was defeated by a Mongol army that captured and sacked Delhi", "body_hi": "उसे एक मंगोल सेना ने हराया जिसने दिल्ली पर क़ब्ज़ा कर उसे लूटा", "isCorrect": false}, {"id": "b", "body": "She was defeated by the Rajputs of Ranthambhor and lost her whole treasury and most of her army", "body_hi": "उसे रणथंभौर के राजपूतों ने हराया और उसका पूरा ख़ज़ाना तथा अधिकांश सेना छिन गई", "isCorrect": false}, {"id": "c", "body": "The ulema declared that the throne must pass to Balban, who was then the senior noble at court", "body_hi": "उलेमा ने घोषणा की कि सिंहासन बलबन को मिलना चाहिए, जो तब दरबार का वरिष्ठ सामंत था", "isCorrect": false}, {"id": "d", "body": "The Turkish nobles resented a woman ruling on her own and her favour to outsiders like Yaqut", "body_hi": "तुर्क सामंतों को एक स्त्री का स्वतंत्र शासन और याक़ूत जैसे बाहरी लोगों को उसका आगे बढ़ाना अखरता था", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'medieval-razia-sultan' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "the royal patronage of Buddhism by the Solanki kings of Gujarat in the face of Brahmanical opposition", "body_hi": "ब्राह्मणवादी विरोध के बीच गुजरात के सोलंकी राजाओं द्वारा बौद्ध धर्म के राजकीय संरक्षण को", "isCorrect": false}, {"id": "b", "body": "the influence of Persian tile-work brought to Gujarat by the Delhi Sultans", "body_hi": "दिल्ली सुल्तानों द्वारा गुजरात लाई गई फ़ारसी टाइल-कला के प्रभाव को", "isCorrect": false}, {"id": "c", "body": "the replacement of stone by brick in the temple architecture of the period", "body_hi": "उस काल के मंदिर स्थापत्य में पत्थर के स्थान पर ईंट के उपयोग को", "isCorrect": false}, {"id": "d", "body": "the wealth of the Jain merchant and official class of western India and its patronage of temples", "body_hi": "पश्चिमी भारत के जैन व्यापारी और अधिकारी वर्ग की संपत्ति और मंदिरों के लिए उसके संरक्षण को", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'art-dilwara-jain-temples' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "It is a festival of lamps celebrating the return of Rama to Ayodhya after his fourteen years of exile", "body_hi": "यह चौदह वर्ष के वनवास के बाद राम के अयोध्या लौटने का उत्सव मनाने वाला दीपों का पर्व है", "isCorrect": false}, {"id": "b", "body": "It honours the goddess Durga''s victory over the buffalo demon Mahishasura", "body_hi": "यह भैंसासुर महिषासुर पर देवी दुर्गा की विजय का सम्मान करता है", "isCorrect": false}, {"id": "c", "body": "It is celebrated by flying kites to mark the sun''s entry into Capricorn", "body_hi": "यह सूर्य के मकर राशि में प्रवेश को पतंगें उड़ाकर मनाया जाता है", "isCorrect": false}, {"id": "d", "body": "Devotees offer arghya to the setting and rising sun at rivers and ponds, with no priest needed", "body_hi": "भक्त नदियों और तालाबों पर डूबते और उगते सूर्य को अर्घ्य देते हैं, किसी पुरोहित की ज़रूरत नहीं होती", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'culture-chhath-surya' returning concept_group_id;
