update public.questions set options = '[{"id": "a", "body": "The Sun''s rays fall vertically on these deserts for most of the year", "body_hi": "इन मरुस्थलों पर वर्ष के अधिकांश समय सूर्य की किरणें लंबवत पड़ती हैं", "isCorrect": false}, {"id": "b", "body": "The trade winds carry hot air from the Equator and pile it up over the deserts", "body_hi": "व्यापारिक पवनें विषुवत रेखा से गर्म वायु लाकर मरुस्थलों के ऊपर जमा कर देती हैं", "isCorrect": false}, {"id": "c", "body": "The deserts stand at higher elevations, which brings them closer to the Sun", "body_hi": "मरुस्थल अधिक ऊँचाई पर हैं, जिससे वे सूर्य के अधिक निकट हो जाते हैं", "isCorrect": false}, {"id": "d", "body": "Clear skies and dry air let most of the Sun''s energy reach the ground", "body_hi": "साफ़ आकाश और शुष्क वायु सूर्य की अधिकांश ऊर्जा को भूमि तक पहुँचने देते हैं", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'geo-hottest-deserts-not-equator' returning concept_group_id;
