update public.questions set options = '[{"id": "a", "body": "warm sea water just offshore keeps feeding storms with heat and moisture throughout the year", "body_hi": "तट के पास का गर्म समुद्री जल साल भर तूफ़ानों को ऊष्मा और नमी देता रहता है", "isCorrect": false}, {"id": "b", "body": "the plains lie at so great a height that thunderclouds form directly inside the jet stream above them", "body_hi": "मैदान इतनी ऊँचाई पर हैं कि गरज वाले बादल सीधे उनके ऊपर की जेट धारा के भीतर बनते हैं", "isCorrect": false}, {"id": "c", "body": "an active fault line beneath the plains releases heat that sets off rising currents of air in spring", "body_hi": "मैदानों के नीचे की एक सक्रिय भ्रंश-रेखा ऊष्मा छोड़ती है जो वसंत में वायु की ऊर्ध्व धाराएँ पैदा करती है", "isCorrect": false}, {"id": "d", "body": "warm, moist air from the south meets cold, dry air from the north, with no range between", "body_hi": "दक्षिण की गर्म, नम वायु उत्तर की ठंडी, शुष्क वायु से मिलती है, और बीच में कोई पर्वत-श्रेणी नहीं है", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'geo-tornadoes-great-plains' returning concept_group_id;
