update public.questions set options = '[{"id": "a", "body": "the lagoon turned fully into a freshwater lake, which suits its fish and its prawns much better", "body_hi": "लैगून पूरी तरह मीठे पानी की झील बन गया, जो इसकी मछलियों और झींगों के लिए कहीं बेहतर है", "isCorrect": false}, {"id": "b", "body": "the whole lagoon drained into the sea and dried up, so the weeds died and the fishing ended", "body_hi": "पूरा लैगून समुद्र में बहकर सूख गया, जिससे खरपतवार मर गई और मछली पकड़ना बंद हो गया", "isCorrect": false}, {"id": "c", "body": "river floods could no longer enter it, so silt stopped reaching its bed and its fish returned", "body_hi": "नदियों की बाढ़ अब इसमें नहीं आ सकती थी, इसलिए गाद इसके तल तक नहीं पहुँची और मछलियाँ लौट आईं", "isCorrect": false}, {"id": "d", "body": "sea water flowed in again, restoring the brackish water on which its fish and prawns depend", "body_hi": "समुद्री जल फिर भीतर आया, और वह खारा-मीठा जल लौटा जिस पर इसकी मछलियाँ और झींगे निर्भर हैं", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'irv-chilika-largest-lagoon' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "the coalfield lies in a flood plain that the Damodar submerges completely in every monsoon season", "body_hi": "कोयला क्षेत्र ऐसे बाढ़-मैदान में है जिसे दामोदर हर मानसून में पूरी तरह डुबो देती है", "isCorrect": false}, {"id": "b", "body": "the coal seams there have been completely exhausted, so the mines and the towns have had to close", "body_hi": "वहाँ की कोयला परतें पूरी तरह समाप्त हो चुकी हैं, इसलिए खदानें और नगर बंद करने पड़े हैं", "isCorrect": false}, {"id": "c", "body": "the land is needed for a large new reservoir to be built on the Subarnarekha river downstream of it", "body_hi": "भूमि की आवश्यकता उसके नीचे की ओर सुवर्णरेखा नदी पर बनने वाले एक बड़े नए जलाशय के लिए है", "isCorrect": false}, {"id": "d", "body": "fires burning for a century in the coal seams below have made the ground unstable and the air toxic", "body_hi": "नीचे की कोयला परतों में सौ वर्षों से जलती आग ने भूमि को अस्थिर और वायु को विषैला बना दिया है", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'res-jharia-coalfield' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "it has replaced cotton as the main fibre for everyday clothing", "body_hi": "इसने रोज़मर्रा के कपड़ों के मुख्य रेशे के रूप में कपास का स्थान ले लिया है", "isCorrect": false}, {"id": "b", "body": "its seeds yield an oil now used widely as a cooking medium", "body_hi": "इसके बीजों से मिलने वाला तेल अब खाना पकाने में व्यापक रूप से काम आता है", "isCorrect": false}, {"id": "c", "body": "it is the only natural fibre that needs no processing at all", "body_hi": "यह अकेला प्राकृतिक रेशा है जिसे किसी प्रसंस्करण की आवश्यकता नहीं होती", "isCorrect": false}, {"id": "d", "body": "it is a biodegradable substitute for plastic packaging", "body_hi": "यह प्लास्टिक पैकेजिंग का जैव-अपघटनीय विकल्प है", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'res-golden-fibre-jute-easy' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "importing high-yielding cattle breeds to replace India''s local cows and buffaloes", "body_hi": "भारत की देशी गायों और भैंसों के स्थान पर अधिक उपज वाली विदेशी नस्लें आयात करके", "isCorrect": false}, {"id": "b", "body": "setting up large state-owned dairy farms on the edge of each of the major cities", "body_hi": "हर बड़े शहर के किनारे बड़े सरकारी डेयरी फ़ार्म स्थापित करके", "isCorrect": false}, {"id": "c", "body": "paying farmers a subsidy to switch from growing grain to keeping dairy animals", "body_hi": "किसानों को अनाज उगाने के बजाय दुधारू पशु पालने के लिए सब्सिडी देकर", "isCorrect": false}, {"id": "d", "body": "linking village milk co-operatives to city markets through a national milk grid", "body_hi": "गाँवों की दुग्ध सहकारी समितियों को राष्ट्रीय दुग्ध ग्रिड के माध्यम से शहरी बाज़ारों से जोड़कर", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'res-operation-flood-milk' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "Bharatmala Pariyojana", "body_hi": "भारतमाला परियोजना", "isCorrect": false}, {"id": "b", "body": "Jal Marg Vikas Project", "body_hi": "जल मार्ग विकास परियोजना", "isCorrect": false}, {"id": "c", "body": "Pradhan Mantri Gram Sadak Yojana", "body_hi": "प्रधानमंत्री ग्राम सड़क योजना", "isCorrect": false}, {"id": "d", "body": "Sagarmala", "body_hi": "सागरमाला", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'tr-sagarmala' returning concept_group_id;
