update public.questions set options = '[{"id": "a", "body": "replace all existing bank accounts with a single national account run by the RBI", "body_hi": "सभी मौजूदा बैंक खातों को RBI द्वारा चलाए जाने वाले एक ही राष्ट्रीय खाते से बदलना", "isCorrect": false}, {"id": "b", "body": "fix a common interest rate for all loans in the country", "body_hi": "देश के सभी ऋणों के लिए एक समान ब्याज दर तय करना", "isCorrect": false}, {"id": "c", "body": "allow the RBI to lend directly to households", "body_hi": "RBI को सीधे परिवारों को उधार देने देना", "isCorrect": false}, {"id": "d", "body": "speed up lending by giving lenders consented access to data from many sources", "body_hi": "ऋणदाताओं को अनेक स्रोतों के डेटा तक सहमति-आधारित पहुँच देकर ऋण देना तेज़ करना", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'fm-unified-lending-interface' returning concept_group_id;
update public.questions set options = '[{"id": "a", "body": "the MEIS had been open only to exporters of farm goods, not manufactures", "body_hi": "MEIS केवल कृषि वस्तुओं के निर्यातकों के लिए थी, विनिर्मित वस्तुओं के लिए नहीं", "isCorrect": false}, {"id": "b", "body": "the RBI had stopped funding the MEIS out of its foreign exchange reserves", "body_hi": "RBI ने अपने विदेशी मुद्रा भंडार से MEIS का वित्तपोषण बंद कर दिया था", "isCorrect": false}, {"id": "c", "body": "the GST Council had asked for all export incentives to be paid by the States", "body_hi": "GST परिषद ने कहा था कि सभी निर्यात प्रोत्साहन राज्य दें", "isCorrect": false}, {"id": "d", "body": "a WTO panel ruled that the MEIS was a prohibited export subsidy", "body_hi": "WTO के एक पैनल ने निर्णय दिया कि MEIS एक निषिद्ध निर्यात सब्सिडी थी", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'ex-rodtep' returning concept_group_id;
