update public.questions set options = '[{"id": "a", "body": "States that raise more taxes of their own receive a correspondingly larger share", "body_hi": "जो राज्य अपने अधिक कर जुटाते हैं, उन्हें उसी अनुपात में अधिक हिस्सा मिलता है", "isCorrect": false}, {"id": "b", "body": "every State receives exactly the same amount per head of its population in 2011", "body_hi": "हर राज्य को उसकी 2011 की जनसंख्या के प्रति व्यक्ति बिल्कुल बराबर राशि मिलती है", "isCorrect": false}, {"id": "c", "body": "States with more dense forest cover receive a larger share, as a reward for conservation", "body_hi": "अधिक सघन वन आवरण वाले राज्यों को संरक्षण के पुरस्कार के रूप में अधिक हिस्सा मिलता है", "isCorrect": false}, {"id": "d", "body": "poorer States receive a larger share than their population alone would give them", "body_hi": "ग़रीब राज्यों को केवल उनकी जनसंख्या से मिलने वाले हिस्से से अधिक हिस्सा मिलता है", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'ft-15th-fc-criteria' returning concept_group_id;
