update public.questions set options = '[{"id": "a", "body": "Firms will rush to build new plants, since a third of their capacity stands idle", "body_hi": "फ़र्में तेज़ी से नए संयंत्र लगाएँगी, क्योंकि उनकी एक-तिहाई क्षमता बेकार पड़ी है", "isCorrect": false}, {"id": "b", "body": "Prices of manufactured goods will rise sharply because supply cannot keep up with demand", "body_hi": "विनिर्मित वस्तुओं की क़ीमतें तेज़ी से बढ़ेंगी क्योंकि आपूर्ति माँग के साथ नहीं चल पा रही", "isCorrect": false}, {"id": "c", "body": "Factories will have to stop production until they can run at full capacity", "body_hi": "कारख़ानों को तब तक उत्पादन रोकना पड़ेगा जब तक वे पूरी क्षमता पर न चल सकें", "isCorrect": false}, {"id": "d", "body": "Firms will put off building new plants until demand picks up", "body_hi": "माँग बढ़ने तक फ़र्में नए संयंत्र लगाने का काम टाल देंगी", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'in-capacity-utilisation' returning concept_group_id;
