update public.questions set options = '[{"id": "a", "body": "internal bays let the aircraft carry more weapons than wing pylons do", "body_hi": "भीतरी खाने विमान को पंखों के तोरणों से अधिक हथियार ले जाने देते हैं", "isCorrect": false}, {"id": "b", "body": "missiles carried outside would freeze solid at high cruising altitudes", "body_hi": "बाहर ले जाई गई मिसाइलें ऊँचाई पर उड़ते समय पूरी तरह जम जाएँगी", "isCorrect": false}, {"id": "c", "body": "international law forbids fighters to show weapons on peacetime patrols", "body_hi": "अंतरराष्ट्रीय क़ानून शांतिकाल की गश्त में लड़ाकू विमानों को हथियार दिखाने से रोकता है", "isCorrect": false}, {"id": "d", "body": "weapons hung outside the body reflect radar waves and spoil its stealth", "body_hi": "ढाँचे के बाहर लटके हथियार रडार तरंगें परावर्तित करते हैं और उसकी गुप्तता बिगाड़ देते हैं", "isCorrect": true}]'::jsonb, updated_at = now() where concept_group_id = 'df-amca' returning concept_group_id;
